results.js:
morse.watch('div.tbl table', table => {
  const tbody = table.querySelector('tbody');
  const th = table.querySelector('th.am');
  if (!tbody || !th || th.dataset.morseSort) return;
  th.dataset.morseSort = '1';
  th.style.cursor = 'pointer';
  th.title = 'Click to sort by amount';
  let asc = false;
  morse.on(th, 'click', () => {
    const rows = Array.from(tbody.querySelectorAll('tr'));
    const val = r => parseFloat((r.querySelector('td.am') || {}).textContent) || 0;
    rows.sort((a, b) => asc ? val(a) - val(b) : val(b) - val(a));
    rows.forEach(r => tbody.appendChild(r));
    asc = !asc;
    th.textContent = 'Amount ' + (asc ? '▲' : '▼');
  });
});

morse.watch('th.am', el => {
  if (el.dataset.sortable) return;
  el.dataset.sortable = '1';
  el.style.cursor = 'pointer';
  el.style.userSelect = 'none';
  el.title = 'Click to sort by amount';
  let asc = false;
  morse.on(el, 'click', () => {
    const table = el.closest('table');
    const tbody = table && table.tBodies[0];
    if (!tbody) return;
    const idx = Array.from(el.parentElement.children).indexOf(el);
    const rows = Array.from(tbody.rows);
    asc = !asc;
    rows.sort((a, b) => {
      const av = parseFloat(String(a.cells[idx]?.textContent).replace(/[^0-9.\-]/g, '')) || 0;
      const bv = parseFloat(String(b.cells[idx]?.textContent).replace(/[^0-9.\-]/g, '')) || 0;
      return asc ? av - bv : bv - av;
    });
    rows.forEach(r => tbody.appendChild(r));
    morse.toast(asc ? 'Sorted by amount, low to high' : 'Sorted by amount, high to low');
  });
});

