morse.on(document, 'keydown', e => {
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  const t = e.target;
  if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
  if (e.key !== 'j' && e.key !== 'k') return;
  const items = [...document.querySelectorAll('[role="option"][data-i]')];
  if (!items.length) return;
  const cur = items.findIndex(el => el.getAttribute('aria-selected') === 'true');
  let next;
  if (cur < 0) next = 0;
  else next = e.key === 'j' ? Math.min(cur + 1, items.length - 1) : Math.max(cur - 1, 0);
  e.preventDefault();
  items[next].click();
  items[next].scrollIntoView({ block: 'nearest' });
});

morse.on(document, "keydown", e => {
  if (e.target.matches("input, textarea, [contenteditable='true']") || e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.key !== "j" && e.key !== "k") return;
  const rows = [...document.querySelectorAll('section[aria-label="Message list"] div.r9[data-i]')];
  if (!rows.length) return;
  const current = rows.findIndex(r => r.getAttribute("aria-selected") === "true");
  const next = e.key === "j" ? Math.min(current + 1, rows.length - 1) : Math.max(current - 1, 0);
  if (next === current) return;
  e.preventDefault();
  const target = rows[next];
  target.click();
  target.scrollIntoView({ block: "nearest" });
  target.focus?.();
});

