morse.watch('div[aria-label="Formatting"]', bar => {
  if (bar.querySelector('.md-date')) return;
  const btn = morse.el('button', {
    class: 'md-date',
    title: 'Insert date',
    text: 'Date',
    on: {
      click: () => {
        const d = new Date();
        const s = d.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
        const sel = window.getSelection();
        const ed = document.querySelector('div[role="textbox"]');
        if (ed) ed.focus();
        if (sel && sel.rangeCount) {
          const r = sel.getRangeAt(0);
          r.deleteContents();
          r.insertNode(document.createTextNode(s));
          r.collapse(false);
        } else if (ed) {
          ed.append(document.createTextNode(s));
        }
        morse.toast('Inserted ' + s);
      }
    }
  });
  bar.append(btn);
});

morse.watch('div[aria-label="Formatting"]', bar => {
  if (bar.querySelector('button.dt')) return;
  const btn = morse.el('button', {
    class: 'dt',
    title: 'Insert today\'s date',
    text: 'Date',
    on: {
      click: () => {
        const d = new Date();
        const text = d.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
        const editor = document.querySelector('div[role="textbox"]');
        if (!editor) return;
        editor.focus();
        const sel = window.getSelection();
        if (sel && sel.rangeCount && editor.contains(sel.anchorNode)) {
          document.execCommand('insertText', false, text);
        } else {
          editor.append(document.createTextNode(text));
        }
      }
    }
  });
  bar.append(btn);
});

