const sidebarKey = "sidebarCollapsed";
const applyState = (collapsed) => {
  document.body.classList.toggle("parley-sidebar-collapsed", collapsed);
  const btn = document.getElementById("parley-sidebar-toggle");
  if (btn) {
    btn.textContent = collapsed ? "»" : "«";
    btn.setAttribute("aria-expanded", String(!collapsed));
    btn.title = collapsed ? "Show sidebar" : "Hide sidebar";
  }
};
let collapsed = morse.store.get(sidebarKey) === true;
morse.watch("body", () => {
  if (document.getElementById("parley-sidebar-toggle")) return;
  const btn = morse.el("button", {
    id: "parley-sidebar-toggle",
    type: "button",
    "aria-label": "Toggle sidebar",
    text: collapsed ? "»" : "«",
    on: {
      click: () => {
        collapsed = !collapsed;
        morse.store.set(sidebarKey, collapsed);
        applyState(collapsed);
      }
    }
  });
  document.body.appendChild(btn);
  applyState(collapsed);
});

