morse.watch('div[data-testid="player-controls"] .btns', (btns) => {
  if (btns.querySelector('[data-morse-sleep]')) return;
  let remaining = 0;
  let timer = null;
  const label = morse.el('span', { text: 'Off', style: 'font: 12px ui-sans-serif; color: currentColor; min-width: 44px; text-align: center;' });
  const tick = () => {
    if (remaining <= 0) { label.textContent = 'Off'; return; }
    const m = Math.floor(remaining / 60), s = remaining % 60;
    label.textContent = m + ':' + String(s).padStart(2, '0');
  };
  const cycle = morse.el('button', {
    'data-morse-sleep': '',
    'aria-label': 'Sleep timer',
    title: 'Sleep timer: click to set 15, 30, 60 min or off',
    text: '☾',
    style: 'background: transparent; color: currentColor; border: 0; cursor: pointer; font-size: inherit;',
    on: { click: () => {
      const steps = [0, 15 * 60, 30 * 60, 60 * 60];
      const next = steps[(steps.indexOf(remaining) + 1) % steps.length];
      remaining = next;
      clearInterval(timer);
      if (remaining > 0) {
        timer = setInterval(() => {
          remaining--;
          tick();
          if (remaining <= 0) {
            clearInterval(timer);
            const pause = document.querySelector('button[data-testid="play-pause"]');
            if (pause && pause.getAttribute('aria-label') === 'Pause') pause.click();
            morse.toast('Sleep timer: playback paused');
          }
        }, 1000);
      }
      tick();
    } }
  });
  btns.append(cycle, label);
  tick();
});

