morse.watch('[data-testid="player-controls"] .btns', btns => {
  const pc = btns.parentElement;
  let endAt = 0;
  let panel;
  const btn = morse.el('button', {
    class: 'sleep-btn', title: 'Sleep timer', 'aria-label': 'Sleep timer', text: '☾',
    on: { click: () => { panel.style.display = panel.style.display === 'flex' ? 'none' : 'flex'; } }
  });
  const set = mins => {
    endAt = mins ? Date.now() + mins * 60000 : 0;
    btn.textContent = mins ? '☾ ' + mins + 'm' : '☾';
    panel.style.display = 'none';
    morse.toast(mins ? 'Sleep timer: ' + mins + ' min' : 'Sleep timer off');
  };
  panel = morse.el('div', { class: 'sleep-panel' },
    ...[15, 30, 45, 60].map(m => morse.el('button', { text: m + ' min', on: { click: () => set(m) } })),
    morse.el('button', { text: 'Off', on: { click: () => set(0) } })
  );
  btns.append(btn);
  pc.append(panel);
  morse.every(1000, () => {
    if (!endAt) return;
    const left = endAt - Date.now();
    if (left > 0) {
      const s = Math.ceil(left / 1000);
      btn.textContent = '☾ ' + Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0');
      return;
    }
    endAt = 0;
    const pp = document.querySelector('button[data-testid="play-pause"]');
    if (pp && pp.getAttribute('aria-label') === 'Pause') pp.click();
    btn.textContent = '☾';
    morse.toast('Sleep timer: playback paused');
  });
});

morse.on(document, 'keydown', e => {
  if (e.key !== ' ' || e.repeat || e.metaKey || e.ctrlKey || e.altKey) return;
  const t = e.target;
  if (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT|BUTTON|A)$/.test(t.tagName)) return;
  const btn = document.querySelector('button[data-testid="play-pause"]');
  if (!btn) return;
  e.preventDefault();
  btn.click();
});

morse.on(document, 'keydown', e => {
